function maxScore(s) {
  let onesRight = 0;
  for (const ch of s) {
    if (ch === '1') {
      onesRight++;
    }
  }

  let zerosLeft = 0;
  let best = 0;
  for (let i = 0; i < s.length - 1; i++) {
    if (s[i] === '0') {
      zerosLeft++;
    } else {
      onesRight--;
    }
    best = Math.max(best, zerosLeft + onesRight);
  }
  return best;
}

