function maxScore(s) {
  let top = -1;
  for (let cut = 1; cut < s.length; cut++) {
    const left = s.slice(0, cut);
    const right = s.slice(cut);
    const score = left.split('').filter(c => c === '0').length + right.split('').filter(c => c === '1').length;
    if (score > top) top = score;
  }
  return top;
}

