function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const length = size === 'large' ? int(400, 500) : int(2, 9);
  const style = rand();
  let s = '';
  if (style < 0.2) {
    // A block of one character followed by a block of the other, sometimes reversed.
    const cut = int(0, length);
    const first = rand() < 0.5 ? '0' : '1';
    const second = first === '0' ? '1' : '0';
    s = first.repeat(cut) + second.repeat(length - cut);
  } else {
    const zeroRate = style < 0.6 ? 0.5 : rand();
    for (let k = 0; k < length; k++) s += rand() < zeroRate ? '0' : '1';
  }
  return [s];
}
